std::vector<int> V1 = {1, 2, 5};
std::vector<int> V2 = {1, 3, 0};
std::vector<int> V3 = {1, 2};

// 1. Operator Overload Comparison
// Lexicographical: V1 < V2 because 2 < 3 at index 1
bool result_op = (V1 < V2); // true

// V3 is a prefix of V1, so V3 < V1
bool result_prefix = (V3 < V1); // true

// 2. Explicit Algorithm Comparison
std::string S1 = "cat";
std::string S2 = "car";

bool lex_compare = std::lexicographical_compare(
    S1.begin(), S1.end(),
    S2.begin(), S2.end()
); // false ('t' > 'r')

// Custom comparison predicate (e.g., comparing only length)
// Note: Requires strict weak ordering
auto length_comp = [](int a, int b) { return a < b; };

bool custom_v_comp = std::lexicographical_compare(
    V3.begin(), V3.end(),
    V1.begin(), V1.end(),
    length_comp
); // true (2 < 5 at index 2)
